// === إعدادات التشابه ===
const HAMMING_MAX = 6;   // كلما قلّ الرقم صار أشد (4-6 جيد)
const SHINGLE_N   = 3;   // 3-grams
const JACCARD_MIN = 0.80;

// === أدوات مساعدة ===
function normalizeText(s) {
  return s.toString()
    .replace(/https?:\/\/\S+/gi, ' ')
    .replace(/[@#]\S+/g, ' ')
    .replace(/\b\d{7,}\b/g, ' ') // أرقام طويلة (تليفونات)
    .replace(/[\u200e\u200f\u202a-\u202e]/g, '')
    .replace(/[ـ]+/g, '')
    .replace(/[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED]/g, '') // تشكيل
    .toLowerCase()
    .replace(/[^a-z0-9\u0600-\u06FF\s]/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

const STOP = new Set([
  'في','من','على','الى','إلى','و','يا','عن','مع','او','أو','ثم','هذا','هذه','ذلك','تلك','كان','كانت',
  'the','a','an','and','or','of','for','to','in','on','at','by','with','is','are','be','as','this','that','these','those'
]);

function tokenize(txt) {
  return txt.split(/\s+/).filter(t => t && !STOP.has(t));
}

function makeShingles(tokens, n = SHINGLE_N) {
  const out = [];
  for (let i = 0; i <= tokens.length - n; i++) out.push(tokens.slice(i, i + n).join(' '));
  return out.length ? out : tokens; // fallback للنصوص القصيرة
}

function hash32(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

function simhash64(features) {
  const weights = {};
  for (const f of features) weights[f] = (weights[f] || 0) + 1;
  const vec = new Array(64).fill(0);
  for (const [feat, w] of Object.entries(weights)) {
    const h1 = hash32(feat);
    const h2 = hash32(feat + '#');
    const hi = (BigInt(h1) << 32n) | BigInt(h2);
    for (let b = 0; b < 64; b++) vec[b] += ((hi >> BigInt(b)) & 1n) ? w : -w;
  }
  let fp = 0n;
  for (let b = 0; b < 64; b++) if (vec[b] > 0) fp |= (1n << BigInt(b));
  return fp;
}

function hamming(a, b) {
  let x = a ^ b, c = 0;
  while (x) { x &= (x - 1n); c++; }
  return c;
}

function jaccard(aSet, bSet) {
  let inter = 0; const b = new Set(bSet);
  for (const x of aSet) if (b.has(x)) inter++;
  const uni = aSet.size + b.size - inter;
  return uni === 0 ? 1 : inter / uni;
}

// === نبني عناقيد تشابه داخل نفس التشغيل ===
const clusters = []; // كل عنصر: {repFp, shingles, items: [itemIdxs], bestIdx}
const prepared = items.map((it, idx) => {
  const text = (it.json.text ?? it.json.text_raw ?? '').toString();
  const norm = normalizeText(text);
  const toks = tokenize(norm);
  const shingles = makeShingles(toks, SHINGLE_N);
  const fp = simhash64(shingles);
  return { idx, it, text, norm, toks, shingles, fp };
});

// قارن كل عنصر بعناقيد موجودة
for (const p of prepared) {
  if (!p.norm) continue;

  let placed = false;
  for (const cl of clusters) {
    const ham = Number(hamming(p.fp, cl.repFp));
    if (ham <= HAMMING_MAX) {
      // احتياط: قياس Jaccard كمان للنصوص القصيرة
      const jac = jaccard(new Set(p.shingles), new Set(cl.shingles));
      if (jac >= JACCARD_MIN || p.shingles.length < 4) {
        cl.items.push(p);
        // اختار "أفضل" نسخة: الأطول ثم الأعلى views إن موجود
        const best = cl.items.reduce((a, b) => {
          const lenA = (a.text || '').length, lenB = (b.text || '').length;
          if (lenA !== lenB) return lenB > lenA ? b : a;
          const va = Number(a.it.json.views ?? 0), vb = Number(b.it.json.views ?? 0);
          return vb > va ? b : a;
        });
        cl.best = best;
        placed = true;
        break;
      }
    }
  }

  if (!placed) {
    clusters.push({ repFp: p.fp, shingles: p.shingles, items: [p], best: p });
  }
}

// رجّع عنصر واحد لكل عنقود + قائمة المصادر اللي اتجمعت
const out = clusters.map(cl => {
  const best = cl.best;
  const sources = cl.items.map(x => ({
    channel: x.it.json.author ?? x.it.json.channel ?? null,
    id: x.it.json.msg_id ?? x.it.json.id ?? null,
    date: x.it.json.date ?? null
  }));
  return {
    json: {
      ...best.it.json,
      text: best.it.json.text ?? best.it.json.text_raw ?? '',
      dedupeSmart: true,
      sources // كل القنوات اللي نشرت نفس الإعلان
    }
  };
});

return out;

// --- Robust JSON Parser (New Schema: HTML + Clean Text) ---

// 1. GET INPUT
const rawOutputString = $input.first()?.json?.output || $input.first()?.json?.text;

// 2. INPUT VALIDATION
if (!rawOutputString || typeof rawOutputString !== 'string') {
  return [{ 
    json: { 
      error: true,
      message: "Input field from AI Agent is missing or not a string." 
    } 
  }];
}

let jsonString = null;

// --- STRATEGY 1: Find Markdown Code Fence (Best for Multiline Strings) ---
const markdownRegex = /`{3,}(?:json|JSON)?\s*([\s\S]*?)\s*`{3,}/;
const markdownMatch = rawOutputString.match(markdownRegex);

if (markdownMatch && markdownMatch[1]) {
  jsonString = markdownMatch[1].trim();
}

// --- STRATEGY 2: Fallback (Brute Force) ---
if (!jsonString) {
  const startIndex = rawOutputString.indexOf('{');
  const endIndex = rawOutputString.lastIndexOf('}');
  if (startIndex > -1 && endIndex > -1 && endIndex > startIndex) {
    jsonString = rawOutputString.substring(startIndex, endIndex + 1).trim();
  }
}

// 3. CHECK IF EXTRACTION FAILED
if (!jsonString) {
  return [{ 
    json: { 
      error: true,
      message: "Could not locate a JSON object in the AI response.",
      rawOutput: rawOutputString
    }
  }];
}

// 4. ATTEMPT PARSING
try {
  const parsedJson = JSON.parse(jsonString);

  // -------------------------------------------------------
  // 5. STRUCTURE VALIDATION & STANDARDIZATION
  // -------------------------------------------------------

  // Ensure the object structure is predictable for the next nodes
  const finalOutput = {
    postType: parsedJson.postType || "OTHER",
    isValidJob: parsedJson.isValidJob === true, // Force Boolean

    // Titles
    arabic_title: parsedJson.arabic_title || null,
    english_title: parsedJson.english_title || null,

    // Formatted HTML (For Telegram)
    // Note: Footer is already included by the AI System Prompt in these fields
    formatted_html: {
      ar: parsedJson.formatted_html?.ar || null,
      en: parsedJson.formatted_html?.en || null
    },

    // Clean Text (For specific use cases/plain text)
    clean_text: {
      ar: parsedJson.clean_text?.ar || null,
      en: parsedJson.clean_text?.en || null
    }
  };

  return [{ json: finalOutput }];

} catch (parseError) {
  return [{ 
    json: {
      error: true,
      message: "Failed to parse JSON.",
      extractedString: jsonString,
      rawOutput: rawOutputString
    }
  }];
}

