const inputs = $input.all();
const output = [];

for (const input of inputs) {
  const messages = input.json.data ?? [];

  for (const item of messages) {
    const message = item.message ?? {};
    const media = message.media ?? {};

    output.push({
      json: {
        ...item,

        id: message.id ?? null,
        text: message.text ?? message.message ?? "",
        date: message.date ?? null,

        chatId: item.chat?.id ?? null,
        chatTitle: item.chat?.title ?? null,
        username: item.chat?.username ?? null,

        hasMedia: media.hasMedia ?? false,
        mediaType: media.type ?? media.mediaType ?? null,
        mediaDownloadStatus: media.downloadStatus ?? null,
        mediaDownloadUrl: media.downloadUrl ?? null,

        photo: {
